SELECT coalesce(toString(properties.$geoip_country_name),'Unknown') AS Country,coalesce(toString(properties.$device_type),'Unknown') AS Device, uniqExact(person_id) AS Visitors FROM events WHERE event = '$pageview' AND (properties.surface IS NULL OR properties.surface = 'web') AND (properties.environment IS NULL OR properties.environment = 'production') AND match(toString(properties.$current_url), '^https://(www[.])?ypr[.]app(/|$)') AND {filters} GROUP BY Country,Device ORDER BY Visitors DESC LIMIT 30
